window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6c2714546130d213"]={"versions": [{"id": "FIG-6c2714546130d213", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Bitfeld-Spezifikation (Datenstruktur-Definition) im Modul <code>AUTOSAR_SWS_Debugging</code>. Das Diagramm definiert das Bit-Layout und die Semantik der Steuerbits (<code>Data Control Bits</code>) für Data Identifier (DID) im Kontext der Datenerfassung und Übertragung an einen Host.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Vier-spaltige Tabelle (<code>Bits</code>, <code>Name</code>, <code>Description</code>, <code>Values</code>) mit drei definierten Bit-Positionen:</p>\n<ul class=\"fig-list\">\n<li>Bit 0: <code>DbgDIDDataCollectionEnabled</code> – Lokaler DID-Status der Datenerfassung; Werte: <code>0 = disabled</code>, <code>1 = enabled</code>.</li>\n<li>Bit 1: <code>DbgDIDTimestampEnabled</code> – Lokales DID-Flag zur Ergänzung von Zeitstempeln zu den Daten; Werte: <code>0 = disabled</code>, <code>1 = enabled</code>.</li>\n<li>Bit 2: <code>DbgDIDBufferStoreEnabled</code> – Lokales DID-Flag zur Pufferung von Daten vor der Host-Übertragung; Werte: <code>0 = disabled (buffer bypass)</code>, <code>1 = enabled</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Bitfeldbelegung ohne dynamische Sequenzabläufe. Die Flags steuern das Laufzeitverhalten der Debugging-Datenerfassung je DID:</p>\n<ul class=\"fig-list\">\n<li>Bit 0 steuert die Aktivierung bzw. Deaktivierung der Erfassung.</li>\n<li>Bit 1 steuert das Anhängen von Zeitstempeln an Datensätze.</li>\n<li>Bit 2 schaltet zwischen direktem Versenden (<code>buffer bypass</code>) und Zwischenspeicherung im Puffer vor der Host-Übertragung um.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Bitfeldstruktur für Implementierer des Debugging-Moduls (Dbg). Die Bitpositionen 0 bis 2 definieren eindeutige binäre Schaltzustände für Datenerfassung, Zeitstempelung und Pufferungsstrategie; nicht explizit aufgeführte höherwertige Bits verbleiben ungenannt bzw. reserviert.</p>"}, {"id": "FIG-9a43699ee1bb59bb", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Bitfeld-Spezifikation (Datenstruktur-Definition) im Modul <code>AUTOSAR_SWS_Debugging</code>. Das Diagramm definiert das Bit-Layout und die Semantik der Steuerbits (<code>Data Control Bits</code>) für Data Identifier (DID) im Kontext der Datenerfassung und Übertragung an einen Host.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Vier-spaltige Tabelle (<code>Bits</code>, <code>Name</code>, <code>Description</code>, <code>Values</code>) mit drei definierten Bit-Positionen:</p>\n<ul class=\"fig-list\">\n<li>Bit 0: <code>DbgDIDDataCollectionEnabled</code> – Lokaler DID-Status der Datenerfassung; Werte: <code>0 = disabled</code>, <code>1 = enabled</code>.</li>\n<li>Bit 1: <code>DbgDIDTimestampEnabled</code> – Lokales DID-Flag zur Ergänzung von Zeitstempeln zu den Daten; Werte: <code>0 = disabled</code>, <code>1 = enabled</code>.</li>\n<li>Bit 2: <code>DbgDIDBufferStoreEnabled</code> – Lokales DID-Flag zur Pufferung von Daten vor der Host-Übertragung; Werte: <code>0 = disabled (buffer bypass)</code>, <code>1 = enabled</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Bitfeldbelegung ohne dynamische Sequenzabläufe. Die Flags steuern das Laufzeitverhalten der Debugging-Datenerfassung je DID:</p>\n<ul class=\"fig-list\">\n<li>Bit 0 steuert die Aktivierung bzw. Deaktivierung der Erfassung.</li>\n<li>Bit 1 steuert das Anhängen von Zeitstempeln an Datensätze.</li>\n<li>Bit 2 schaltet zwischen direktem Versenden (<code>buffer bypass</code>) und Zwischenspeicherung im Puffer vor der Host-Übertragung um.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Bitfeldstruktur für Implementierer des Debugging-Moduls (Dbg). Die Bitpositionen 0 bis 2 definieren eindeutige binäre Schaltzustände für Datenerfassung, Zeitstempelung und Pufferungsstrategie; nicht explizit aufgeführte höherwertige Bits verbleiben ungenannt bzw. reserviert.</p>"}, {"id": "FIG-b4482318c0fdb721", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Fragmentierte tabellarische Bitfeld-Spezifikation im Modul <code>AUTOSAR_SWS_Debugging</code>. Das Diagramm zeigt ein unvollständiges Bit-Layout der Steuerbits (<code>Data Control Bits</code>) für Data Identifier (DID) ohne sichtbare Tabellenkopfzeile.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dreizeilige Tabelle mit beschädigter Struktur und fehlendem Spaltenkopf:</p>\n<ul class=\"fig-list\">\n<li>Erste Zeile: Fragmentierter Eintrag ohne Bit-Index und Bezeichner; enthält nur das Textfragment <code>collection</code> und den Wert <code>1 = enabled</code>.</li>\n<li>Zweite Zeile: Bit 1 <code>DbgDIDTimestampEnabled</code> – Flag zur Zeitstempelergänzung; Werte: <code>0 = disabled</code>, <code>1 = enabled</code>.</li>\n<li>Dritte Zeile: Bit 2 <code>DbgDIDBufferStoreEnabled</code> – Flag zur Pufferung vor Host-Übertragung; Werte: <code>0 = disabled (buffer bypass)</code>, <code>1 = enabled</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Bitfeldbelegung ohne dynamische Sequenzabläufe. Die Flags steuern das Laufzeitverhalten der Debugging-Datenerfassung je DID:</p>\n<ul class=\"fig-list\">\n<li>Bit 0 steuert die Aktivierung bzw. Deaktivierung der Erfassung.</li>\n<li>Bit 1 steuert das Anhängen von Zeitstempeln an Datensätze.</li>\n<li>Bit 2 schaltet zwischen direktem Versenden (<code>buffer bypass</code>) und Zwischenspeicherung im Puffer vor der Host-Übertragung um.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Aufgrund eines Formatierungs- bzw. Schnittfehlers fehlen in dieser Fassung der Tabellenkopf sowie die Definition von Bit 0 (<code>DbgDIDDataCollectionEnabled</code> mit Wert <code>0 = disabled</code>). Für Implementierer ist die Bitfeldbelegung an Position 0 normativ unvollständig dargestellt. Bit 1 und Bit 2 sind weiterhin mit ihren Werten spezifiziert.</p>"}], "trans": [{"from": "FIG-6c2714546130d213", "to": "FIG-9a43699ee1bb59bb", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9a43699ee1bb59bb", "to": "FIG-b4482318c0fdb721", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kopfzeile der Tabelle (Spaltenbezeichnungen <code>Bits</code>, <code>Name</code>, <code>Description</code>, <code>Values</code>) sowie graue Hinterlegung der Kopfzeile entfernt bzw. abgeschnitten.</li>\n<li>Bit 0 (<code>DbgDIDDataCollectionEnabled</code>, Beschreibung <code>DID local status of data collection</code>, Werte <code>0 = disabled</code>, <code>1 = enabled</code>) ist fehlerhaft abgeschnitten; die erste Tabellenzeile enthält nur noch das Fragment <code>collection</code> und <code>1 = enabled</code>.</li>\n<li>Zeilenanzahl der Tabelle reduziert sich von 4 auf 3 Zeilen (Höhe 278 px auf 222 px verringert).</li>\n</ul>"}]};
